'use strict';
// Actual bundled HTML scripts; DOM stub preserves handlers and detects destructive innerHTML replacement.
const {test}=require('node:test'),a=require('node:assert/strict'),vm=require('node:vm'),fs=require('node:fs');
class Element {
 constructor(tag='div'){this.tag=tag;this.children=[];this.style={setProperty(){}};this.dataset={};this.value='customer';this._html='';this.textContent='';this.disabled=false;}
 set innerHTML(value){this._html=value;this.children=[];} get innerHTML(){return this._html;}
 append(element){this.children.push(element);} replaceChildren(){this.children=[];}
}
function harness(){const els={},timers=[];const all=(el)=>[el,...el.children.flatMap(all)];const ctx=vm.createContext({URLSearchParams,TextEncoder,console,setTimeout:fn=>{timers.push(fn);return timers.length;},clearTimeout:()=>{},document:{getElementById:id=>els[id]||(els[id]=new Element),createElement:tag=>new Element(tag),querySelectorAll:()=>Object.values(els).flatMap(all).filter(e=>e.dataset.action)}});const html=fs.readFileSync(__dirname+'/demo.html','utf8');for(const script of html.matchAll(/<script>([\s\S]*?)<\/script>/g))vm.runInContext(script[1],ctx);const run=x=>vm.runInContext(x,ctx);const buttons=()=>all(els.chat).filter(e=>e.tag==='button');const latestButton=(action,item='I01')=>all(els.chat.children.at(-1)).find(e=>e.dataset.action===action&&e.dataset.item===item);return {els,run,html,buttons,latestButton,all,release:()=>run('unlock()')};}
test('HTML真實事件處理器仍可點擊，出新版保留舊卡',()=>{const h=harness();a.equal(h.els.chat.children.length,1);const old=h.latestButton('report');a.equal(typeof old.onclick,'function');old.onclick();a.equal(h.run('model().state.version'),2);a.equal(h.els.chat.children.length,2);a.equal(h.run('model().state.items[0].reported'),true);h.release();old.onclick();a.equal(h.run('model().state.version'),2);a.match(h.els.notice.textContent,/舊卡/);});
test('HTML重复event、連點、未知ID防護',()=>{const h=harness();h.latestButton('report').onclick();h.els.duplicate.onclick();a.equal(h.run('model().state.version'),2);a.match(h.els.notice.textContent,/相同事件/);h.release();h.els.burst.onclick();a.equal(h.run('model().state.version'),3);a.match(h.els.notice.textContent,/連點/);h.els.unknown.onclick();a.equal(h.run('model().state.version'),3);a.match(h.els.notice.textContent,/未知文件/);});
test('HTML客戶申請與承辦核定兩層，角色切換不產生新版本',()=>{const h=harness();h.latestButton('requestNotApplicable').onclick();a.equal(h.run('model().state.items[0].applicable'),true);a.equal(h.latestButton('approveNotApplicable'),undefined);h.els.role.value='staff';h.els.role.onchange();a.equal(h.run('model().state.version'),2);a.match(h.els.roleHint.textContent,/非正式登入/);h.latestButton('approveNotApplicable').onclick();a.equal(h.run('model().state.items[0].applicable'),false);});
test('HTML個案切換各自延續，跨case旧卡不可修改當前case',()=>{const h=harness();const old=h.latestButton('report');old.onclick();h.els.scenario.value='self';h.els.scenario.onchange();a.equal(h.run('model().state.version'),1);h.release();old.onclick();a.equal(h.run('model().state.version'),1);a.match(h.els.notice.textContent,/個案不符/);h.els.scenario.value='salary';h.els.scenario.onchange();a.equal(h.run('model().state.version'),2);a.equal(h.els.chat.children.length,2);});
test('HTML長清單畫面與JSON包含26客戶文件、7頁，公司及後段不計主要完成率',()=>{const h=harness();h.els.scenario.value='long';h.els.scenario.onchange();a.equal(h.run('model().state.items.length'),26);a.equal(JSON.parse(h.els.json.textContent).contents.contents.length,7);a.match(h.els.caseLabel.textContent,/非客戶必備清單/);a.equal(h.run('C.progress(model().state).total'),16);a.equal(h.buttons().length,52);a.ok(!h.all(h.els.chat).some(e=>e.dataset.company));});
test('自包含HTML無外部腳本、網路調用、檔案上傳或秘密欄位',()=>{const h=harness();a.ok(!/<script[^>]+src=/.test(h.html));a.ok(!/\bfetch\(|XMLHttpRequest|type="file"/.test(h.html));a.match(h.html,/示範資料，未連線 LINE/);a.match(h.html,/沒有寄送訊息/);a.match(h.html,/自報不等於承辦收件確認/);});
test('HTML客戶卡只列財力，沒有公司送件按鈕或公司待交',()=>{const h=harness();a.match(h.html,/<h1>房貸財力資料清單<\/h1>/);a.equal(h.buttons().length,2);a.equal(h.latestButton('companySubmit','A01'),undefined);a.ok(!h.all(h.els.chat).some(e=>['A01','A06','A07'].includes(e.dataset.item)||e.dataset.company));a.equal(h.run('C.progress(model().state).total'),1);a.equal(h.run('model().state.companyItems.some(i=>i.submitted)'),false);});
test('HTML承辦公司責任區需另行標記，切回客戶不顯示公司卡',()=>{const h=harness();h.els.role.value='staff';h.els.role.onchange();const b=h.latestButton('companySubmit','A01');a.equal(typeof b.onclick,'function');a.equal(h.run('model().state.companyItems[0].submitted'),false);b.onclick();a.equal(h.run('model().state.companyItems[0].submitted'),true);a.equal(h.run('C.progress(model().state).verified'),0);h.els.role.value='customer';h.els.role.onchange();a.equal(h.latestButton('companySubmit','A06'),undefined);a.ok(!h.all(h.els.chat).some(e=>e.dataset.company));});
test('HTML混合收入、適用稅表、補充資產不全量展開',()=>{const h=harness();for(const [scenario,ids] of [['mixed',['I01','I06']],['self401',['T401']],['self403',['T403']],['self405',['T405']],['assets',['I01','S01']]]){h.els.scenario.value=scenario;h.els.scenario.onchange();a.deepEqual(JSON.parse(h.run('JSON.stringify(model().state.items.map(i=>i.id))')),ids);}a.equal(h.run('C.progress(model().state).total'),1);});
